import { MemoryStore } from '../core/store.js';

export class TypeScriptTypeGenerator {
  public static generate(store: MemoryStore): string {
    const lines: string[] = [
      '/**',
      ' * Auto-generated by ApiCrafter (https://github.com/raghav1924/apicrafter)',
      ' * Author: Jatin Sharma (https://jatinsh.netlify.app/)',
      ' */\n',
    ];

    for (const name of store.getCollections()) {
      const schema = store.getSchema(name);
      const typeName = this.capitalize(name.endsWith('s') ? name.slice(0, -1) : name);

      lines.push(`export interface ${typeName} {`);
      if (schema && schema.fields.length > 0) {
        for (const field of schema.fields) {
          lines.push(`  ${field.name}: ${this.mapTsType(field.type)};`);
        }
      } else {
        // Infer from data
        const items = store.getAll(name) || [];
        if (items.length > 0) {
          for (const [k, v] of Object.entries(items[0])) {
            lines.push(`  ${k}: ${typeof v};`);
          }
        } else {
          lines.push(`  id: string;`);
          lines.push(`  [key: string]: any;`);
        }
      }
      lines.push(`}\n`);
    }

    return lines.join('\n');
  }

  private static mapTsType(type: string): string {
    switch (type) {
      case 'number':
        return 'number';
      case 'boolean':
        return 'boolean';
      case 'date':
      case 'email':
      case 'uuid':
      case 'id':
      case 'string':
      default:
        return 'string';
    }
  }

  private static capitalize(s: string): string {
    return s.charAt(0).toUpperCase() + s.slice(1);
  }
}
